import json

def recommend_car_size(height):
    car_sizes = json.loads('''{
                                "carSizes": {
                                    "compact": {"name": "Compact", "heightRange": "4'6\" - 5'2\"", "length": "14 - 16 feet"},
                                    "midsize": {"name": "Midsize", "heightRange": "5'3\" - 5'5\"", "length": "16 - 18 feet"},
