Sure! Here's a simple JavaScript function that switches the order of adjectives in a sentence:

```javascript
function switchAdjectives(sentence) {
  // Split the sentence into an array of words
  const words = sentence.split(" ");

  // Reverse the order of the adjectives (words starting with 'beautiful', 'green', etc.)
  const adjectives = words.filter(word => word.startsWith('beautiful') || word.startsWith('green'));
  adjectives.reverse();

  // Reconstruct the sentence with the reversed adjectives
  const newSentence = adjectives.join(" ") + " " + words.filter(word => !word.startsWith('beautiful') && !word.startsWith('green')).join(" ");

  return newSentence;
}

// Test the function with your example sentence
const sentence = "Beautiful green trees are in the park";
const newSentence = switchAdjectives(sentence);
console.log(newSentence); // Output: Green beautiful trees are in the park
```

