Here's a JavaScript function that accepts text and posts messages via the Slack API to a specified channel:

```javascript
const axios = require('axios');

async function postToSlack(text, channel) {
  const url = `https://slack.com/api/chat.postMessage?channel=${channel}&text=${encodeURIComponent(text)}`;
  const headers = {
    'Authorization': `Bearer ${process.env.SLACK_API_KEY}`,
    'Content-Type': 'application/x-www-form-urlencoded'
  };

  try {
    const response = await axios.post(url, null, { headers });
    console.log(`Message posted to ${channel}: ${text}`);
    return response.data;
  } catch (error) {
    console.error(`Error posting message to ${channel}: ${error}`);
    throw error;
  }
}

// Example usage
postToSlack('Hello, world!', '#general').then((response) => {
  console.log(response);
}).catch((error) => {
  console.error(error);
});
```

Make sure to replace `process.env.SLACK_API_KEY` with your actual Slack API key.

