Here's a C++ program that meets your requirements:

```cpp
#include <iostream>
#include <string>
#include <sstream>
#include <vector>

using namespace std;

// Recursive function to generate the Fibonacci sequence
void generateFibonacci(int n, int a, int b) {
    if (n == 0) {
        return;
    }

    cout << a << " ";
    generateFibonacci(n - 1, b, a + b);
}

int main() {
    string input;
    vector<int> nums;

    // Prompt the user to input the first two integers
    cout << "Enter the first two integers (separated by a space): ";
    getline(cin, input);

    // Split the input string into a vector of integers
    istringstream iss(input);
    int num;
    while (iss >> num) {
        nums.push_back(num);
    }

    // Validate the input
    if (nums.size() != 2 || nums[0] < 0 || nums[1] < 0) {
        cerr << "Invalid input. Please enter two positive integers." << endl;
        return 1;
    }

    // Prompt the user to input the number of sequence elements to generate
    cout << "Enter the number of sequence elements to generate: ";
    cin >> num;

    // Generate the Fibonacci sequence
    generateFibonacci(num, nums[0], nums[1]);

    return 0;
}
```

This program prompts the user to input the first two integers and the number of sequence elements to generate. It then validates the input and generates the Fibonacci sequence using a recursive function. The generated sequence is outputted with each element separated by a comma and a space. If the input is invalid, an error message is displayed and the program exits with a status code of 1.

