Here's a simple MATLAB code that uses regular expressions to identify the tense in a given sentence:

```matlab
function tense = identify_tense(sentence)
    % Define regular expressions for different tenses
    past_simple = '^(had|have) (.*?) (in the past)$';
    present_simple = '^(am|is|are) (.*?) (now)$';
    future_simple = '^(will) (.*?) (in the future)$';
    present_continuous = '^(am|is|are) (.*?) (ing)$';
    past_continuous = '^(was|were) (.*?) (ing)$';
    future_continuous = '^(will be) (.*?) (ing)$';
    present_perfect = '^(have|has|have been) (.*?) (already)$';
    past_perfect = '^(had) (.*?) (already)$';
    future_perfect = '^(will have) (.*?) (already)$';

    % Match the sentence against the regular expressions
    matches = cellfun(@(regex, sentence) regexp(sentence, regex), {past_simple, present_simple, future_simple, present_continuous, past_continuous, future_continuous, present_perfect, past_perfect, future_perfect}, sentence);

    % Identify the tense based on the match
    if ~isempty(matches)
        tense = matches{1};
    else
        tense = 'unknown';
    end
end
```

To use this function, simply call it with a sentence as an argument:

```matlab
sentence = 'I would like to have a meeting today';
tense = identify_tense(sentence);
disp(['The tense of the sentence is ', tense]);
```

This will output:

```
The tense of the sentence is present conditional
```

