Here's a simple Go program that parses a struct in a Go source file and generates an Avro schema from it:

```go
package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"log"
	"reflect"
)

type StructInfo struct {
	Name       string `json:"name"`
	Fields    []Field `json:"fields"`
}

type Field struct {
	Name   string `json:"name"`
	Type   string `json:"type"`
	Nullable bool `json:"nullable"`
}

func main() {
	file := "example.go"
	structName := "MyStruct"

	data, err := ioutil.ReadFile(file)
	if err != nil {
		log.Fatal(err)
	}

	var info StructInfo
	err = json.Unmarshal(data, &info)
	if err != nil {
		log.Fatal(err)
	}

	schema, err := generateSchema(info, structName)
	if err != nil {
		log.Fatal(err)
	}

	err = ioutil.WriteFile("struct.avsc", schema, 0644)
	if err != nil {
		log.Fatal(err)
	}
}

func generateSchema(info StructInfo, structName string) ([]byte, error) {
	schemaDef := fmt.Sprintf("{%s}", structName)

	for _, field := range info.Fields {
		fieldType := reflect.TypeOf(field.Type).String()
		if field.Nullable {
			fieldType += "?"
		}

		schemaDef += fmt.Sprintf(", %s %s", field.Name, fieldType)
	}

	schemaDef += "}"

	return []byte(schemaDef), nil
}
```

This program reads the content of a Go source file (specified by the `file` variable) and extracts the name of the struct you want to convert (specified by the `structName` variable). It then generates an Avro schema for the

