Here's a Python script that uses `argparse` to read parameters, fetches all failed workflows, retrieves their inputs and names, and then re-executes them by using the same input as the original workflow and the same name but adding a "retry" suffix at the end:

```python
import boto3
import argparse

def get_failed_workflows(step_function_client):
    failed_workflows = []
    response = step_function_client.list_workflows(
        WorkflowStatusFilter=[
            'Failed',
        ]
    )
    for workflow in response['Workflows']:
        if workflow['Status'] == 'Failed':
            failed_workflows.append(workflow)
    return failed_workflows

def get_workflow_inputs(step_function_client, workflow_arn):
    input_definitions = []
    response = step_function_client.get_workflow(
        WorkflowId=workflow_arn
    )
    for definition in response['WorkflowDefinition']['InputDefinitions']:
        input_definitions.append({
            'Name': definition['Name'],
            'Type': definition['Type'],
            'DefaultValue': definition['DefaultValue'],
            'Description': definition['Description'],
        })
    return input_definitions

def re_execute_workflow(step_function_client, workflow_arn, input_definitions, retry_suffix):
    new_workflow_name = f"{workflow_arn} {retry_suffix}"
    new_input_definitions = {}
    for input_definition in input_definitions:
        new_input_definitions[input_definition['Name']] = input_definition['DefaultValue']
    response = step_function_client.start_workflow_execution(
        WorkflowId=new_workflow_name,
        Input=new_input_definitions,
        ClientToken='unique-client-token',
    )
    print(f"Re-executing workflow '{workflow_arn}' with retry suffix '{retry_suffix}'.")
    return response

