To create a simple toast notification using React context, follow these steps:

1. Create a ToastContext file:

```javascript
import React, { createContext, useReducer } from 'react';

const initialState = {
  isOpen: false,
  message: '',
};

const toastReducer = (state, action) => {
  switch (action.type) {
    case 'OPEN_TOAST':
      return { ...state, isOpen: true, message: action.message };
    case 'CLOSE_TOAST':
      return { ...state, isOpen: false, message: '' };
    default:
      return state;
  }
};

export const ToastContext = createContext({
  ...initialState,
  toastReducer,
});

export const ToastProvider = ({ children }) => {
  const [state, dispatch] = useReducer(toastReducer, initialState);

  const openToast = (message) => {
    dispatch({ type: 'OPEN_TOAST', message });
  };

  const closeToast = () => {
    dispatch({ type: 'CLOSE_TOAST' });
  };

  return (
    <ToastContext.Provider value={{ state, openToast, closeToast }}>
      {children}
    </ToastContext.Provider>
  );
};
```

2. Import the ToastContext and ToastProvider in your main application component:

```javascript
