And here's the `createBarChart` function:

```typescript
function createBarChart(data: number[]): HTMLCanvasElement {
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d');

  const width = 400;
  const height = 200;
  canvas.width = width;
  canvas.height = height;

  // Set up the chart
  const margin = { top: 20, right: 20, bottom: 30, left: 40 };
  const x = d3.scaleBand().range([margin.left, width - margin.right]).padding(0.1);
  const y = d3.scaleLinear().range([height - margin.bottom, margin.top]);

  x.domain(data.map((d) => d));
  y.domain([0, d3.max(data)!]);

  // Draw the bars
  ctx.beginPath();
  ctx.moveTo(x(data[0]), y(data[0]));
  for (let i = 1; i < data.length; i++) {
    ctx.lineTo(x(data[i]), y(data[i]));
  }
  ctx.closePath();
  ctx.fillStyle = 'blue';
  ctx.fill();

  return canvas;
}
```

