To identify if a given sentence in Go contains a double negative, you can follow these steps:

1. Create a slice of specific negative words.
2. Check if the sentence contains any of them.
3. Check if the sentence contains the phrase "not" followed by that negative word.
4. If both conditions are satisfied, print a message indicating that the sentence contains a double negative.

Here's the Go code to accomplish this task:

```go
package main

import (
	"fmt"
	"strings"
)

func main() {
	negativeWords := []string{"not", "never", "no", "none", "nothing"}
	sentence := "He isn't not worried about the coronavirus situation"

	if containsNegativeWord(sentence, negativeWords) && containsNotFollowedByNegativeWord(sentence, negativeWords) {
		fmt.Println("The sentence contains a double negative.")
	} else {
		fmt.Println("The sentence does not contain a double negative.")
	}
}

func containsNegativeWord(sentence string, negativeWords []string) bool {
	for _, word := range negativeWords {
		if strings.Contains(sentence, word) {
			return true
		}
	}
	return false
}

func containsNotFollowedByNegativeWord(sentence string, negativeWords []string) bool {
	words := strings.Split(sentence, " ")
	for i, word := range words {
		if word == "not" && i+1 < len(words) && negativeWords.Contains(words[i+1]) {
			return true
		}
	}
	return false
}
```

In this code, we first create a slice of specific negative words. Then, we check if the sentence contains any of them using the `containsNegativeWord` function. Finally, we check if the sentence contains the phrase "not" followed by that negative word using the `containsNotFollowedByNegativeWord` function. If both conditions are satisfied, we print a message indicating that the sentence contains a double negative. Otherwise, we print a message indicating that the sentence does not contain a double

